'use strict';

// MODULES //

var arraylike2object = require( '@stdlib/array/base/arraylike2object' );
var accessors = require( './accessors.js' );


// MAIN //

/**
* Sorts a strided array using insertion sort according to a provided callback function and using alternative indexing semantics.
*
* @param {PositiveInteger} N - number of indexed elements
* @param {Collection} x - input array
* @param {integer} strideX - stride length
* @param {NonNegativeInteger} offsetX - starting index
* @param {Callback} clbk - callback function
* @param {*} [thisArg] - execution context
* @returns {Collection} input array
*
* @example
* var x = [ 1.0, -2.0, 3.0, -4.0 ];
*
* function clbk( a, b ) {
*     if ( a < b ) {
*         return -1;
*     }
*     if ( a > b ) {
*         return 1;
*     }
*     return 0;
* }
*
* gsortinsBy( x.length, x, 1, 0, clbk );
* // x => [ -4.0, -2.0, 1.0, 3.0 ]
*/
function gsortinsBy( N, x, strideX, offsetX, clbk ) {
	var thisArg;
	var ix;
	var jx;
	var fx;
	var ox;
	var v;
	var u;
	var i;

	if ( arguments.length > 5 ) {
		thisArg = arguments[ 5 ];
	}
	if ( N <= 0 ) {
		return x;
	}
	ox = arraylike2object( x );
	if ( ox.accessorProtocol ) {
		accessors( N, ox, strideX, offsetX, clbk, thisArg );
		return x;
	}
	fx = offsetX; // first index
	ix = fx + strideX;

	if ( strideX < 0 ) {
		// Traverse the strided array from right-to-left...
		for ( i = 1; i < N; i++ ) {
			v = x[ ix ];
			jx = ix - strideX;

			// Shift all larger values to the right of the current element to the left...
			while ( jx <= fx ) {
				u = x[ jx ];
				if ( clbk.call( thisArg, u, v, x ) <= 0 ) {
					break;
				}
				x[ jx+strideX ] = u;
				jx -= strideX;
			}
			x[ jx+strideX ] = v;
			ix += strideX;
		}
		return x;
	}
	// Traverse the strided array from left-to-right...
	for ( i = 1; i < N; i++ ) {
		v = x[ ix ];
		jx = ix - strideX;

		// Shift all larger values to the left of the current element to the right...
		while ( jx >= fx ) {
			u = x[ jx ];
			if ( clbk.call( thisArg, u, v, x ) <= 0 ) {
				break;
			}
			x[ jx+strideX ] = u;
			jx -= strideX;
		}
		x[ jx+strideX ] = v;
		ix += strideX;
	}
	return x;
}


// EXPORTS //

module.exports = gsortinsBy;
